-- Public portfolio demonstration coupons. Existing vouchers are never reset.
SELECT 'DEMO20',20.00,100,0 WHERE NOT EXISTS (SELECT 1 FROM vouchers WHERE code='DEMO20');
SELECT 'DEMO50',50.00,100,0 WHERE NOT EXISTS (SELECT 1 FROM vouchers WHERE code='DEMO50');
SELECT 'DEMO100',100.00,100,0 WHERE NOT EXISTS (SELECT 1 FROM vouchers WHERE code='DEMO100');

